export function englishProjectTitle(fieldId,topicId,projectId=1){
 const topics=PROJECT_SUBJECTS[String(fieldId)]??['Uncertainty and reproducibility in a research model','Evidence and method validation in a field study','Robustness under changing research conditions'];
 let hash=2166136261;for(const character of `${topicId??''}:${projectId}`)hash=Math.imul(hash^character.charCodeAt(0),16777619)>>>0;
 const index=Math.max(0,Math.trunc(Number(projectId)||1)-1),subtitles=String(fieldId)==='048'?['a foundational argument','assumption sensitivity','boundary conditions','sharp bounds','limiting behavior','an extended construction','a comparative proof','a refined counterexample']:['a foundational analysis','assumption sensitivity','boundary conditions','robustness and limitations','a comparative evaluation','extended validation','uncertainty analysis','methodological synthesis'];
 return `${topics[hash%topics.length]}: ${subtitles[index%subtitles.length]}${index>=subtitles.length?` (series ${Math.floor(index/subtitles.length)+1})`:''}`;
}

export function englishArtworkLabel(value){return String(value).split(' · ').map(part=>CONTENT_EN[part]??part.replace(/^앞머리 (\d+)$/,'Fringe $1')).join(' · ');}
export function localizeArtworkLabels(svg){return svg.replace(/aria-label="([^"]*)"/g,(_,label)=>`aria-label="${englishArtworkLabel(label)}"`).replace(/<title>([^<>]*)<\/title>/g,(_,title)=>`<title>${englishArtworkLabel(title)}</title>`);}
